import {esc} from '../editor/model.js';
import {icon} from '../../shared/icons.js';
import {algorithmName} from '../editor/algorithm-inputs.js';
import {createMolecule,moleculeFormula} from '../editor/molecule.js';
export const moleculeRecordsKey='forge-molecular-models-v1';
const deletedMoleculesKey='forge-molecular-models-deleted-v1';
export function deletedMoleculeIds(){try{return new Set(JSON.parse(localStorage.getItem(deletedMoleculesKey)||'[]'));}catch{return new Set();}}
export function deleteMolecularRecord(id){const removed=deletedMoleculeIds();removed.add(id);localStorage.setItem(deletedMoleculesKey,JSON.stringify([...removed]));localStorage.setItem(moleculeRecordsKey,JSON.stringify(localMoleculeRecords().filter(r=>r.id!==id)));}
export function localMoleculeRecords(){let saved=[];try{const data=JSON.parse(localStorage.getItem(moleculeRecordsKey)||'[]');if(Array.isArray(data))saved=data;}catch{}const samples=['benzene','ethanol','ammonia','methane','water','butane'].map(preset=>{const molecule=createMolecule(preset);return {id:'molecular-sample-'+preset,name:molecule.name+' · 分子示例',molecule,time:'',sample:true};});return [...saved,...samples.filter(r=>!saved.some(item=>item.id===r.id))].filter(r=>!deletedMoleculeIds().has(r.id));}
export function modelingRecords(workflows,load){
 const molecular=localMoleculeRecords().map(r=>({...r,local:true})),cross=[];
 for(const w of workflows){const s=load(w),macro=s.nodes.find(n=>n.type==='macro');cross.push({workflow:w,state:s,macro});
  for(const n of s.nodes.filter(n=>n.type==='micro'&&n.params.molecule))molecular.push({id:w.id+':'+n.id,name:n.name.replace(' · 微观建模',''),molecule:n.params.molecule,workflow:w,state:s,node:n,time:w.updatedAt});
 }
 return {molecular:molecular.filter(r=>!deletedMoleculeIds().has(r.id)),cross};
}
export function moleculeThumbnail(m){
 const atoms=(m.atoms||[]).map(a=>({...a,x:a.x+(a.z||0)*.38,y:a.y+(a.z||0)*.25})),xs=atoms.map(a=>a.x),ys=atoms.map(a=>a.y),cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2,scale=Math.min(24,110/Math.max(1,Math.max(...xs)-Math.min(...xs)),78/Math.max(1,Math.max(...ys)-Math.min(...ys)));
 const point=a=>[80+(a.x-cx)*scale,58-(a.y-cy)*scale];
 return `<svg viewBox="0 0 160 116" role="img" aria-label="${esc(m.name)}分子模型缩略图">${(m.bonds||[]).map(b=>{const a=atoms[b.from],c=atoms[b.to];if(!a||!c)return '';const [x,y]=point(a),[xx,yy]=point(c);return `<path d="M${x} ${y}L${xx} ${yy}" stroke="#9da7b9" stroke-width="${b.order>1?4:3}"/>`;}).join('')}${atoms.map(a=>{const [x,y]=point(a);return `<circle cx="${x}" cy="${y}" r="${a.element==='H'?4:7}" fill="${({H:'#e1e5ee',O:'#cd8585',N:'#879bc4',C:'#6e648d'})[a.element]||'#b6a375'}" stroke="#fff" stroke-width="1.3"/>`;}).join('')}</svg>`;
}
export function macroThumbnail(n){
 const p=n?.params||{};let model='';
 if(p.case==='extrusion'||p.geometryKind==='pipe'){model='<path d="M18 37 58 34 77 43 103 42 143 51 143 65 103 72 77 72 58 82 18 79Z" fill="#c4cfdd" stroke="#8295ac"/><path d="M58 34v48m19-39v29m26-30v30" fill="none" stroke="#8b9cb2"/><ellipse cx="18" cy="58" rx="7" ry="21" fill="#dbe2ec" stroke="#8295ac"/>';}
 else if(p.blankGeometry&&!p.materials?.length&&!p.modeling?.primitives?.length){model='<path d="M53 43 80 29l27 14v32L80 89 53 75Z M53 43l27 14 27-14M80 57v32" fill="none" stroke="#b6bfd1" stroke-width="1.5" stroke-dasharray="4 4"/>';}
 else{const particles=Array.from({length:12},(_,i)=>{const x=48+(i%4)*20+(Math.floor(i/4)%2)*5,y=49+Math.floor(i/4)*15;return p.materials?.filter(m=>m.region==='filler').some(m=>m.shape==='platelet')&&i%2?`<path d="m${x-6} ${y-6} 13-3 3 11-13 3Z" fill="#94b7c5" stroke="#7396a5"/>`:`<circle cx="${x}" cy="${y}" r="6" fill="#b798df" stroke="#d5c3ed"/>`;}).join('');model='<path d="M31 34 92 22l40 21v51l-62 13-39-22Z" fill="#e9eef6" fill-opacity=".7" stroke="#a2b1c7"/>'+particles+'<path d="m31 34 39 21 62-12M70 55v52M92 22v51" fill="none" stroke="#a2b1c7"/>';}
 return `<svg viewBox="0 0 160 116" role="img" aria-label="${esc(algorithmName(p.case))}模型缩略图">${model}</svg>`;
}
function alternateCreateArt(id){
 if(id==='molecule')return '<g class="animated-molecule"><path d="m95 25 35 21v42l-35 22-35-22V46Z M65 50l30-18 29 18M124 83 95 102 66 83" fill="none"/><circle cx="95" cy="25" r="8"/><circle cx="130" cy="46" r="8"/><circle cx="130" cy="88" r="8"/><circle cx="95" cy="110" r="8"/><circle cx="60" cy="88" r="8"/><circle cx="60" cy="46" r="8"/></g>';
 if(id==='tim')return '<g class="animated-tim"><path d="m43 35 60-13 43 22v60l-60 15-43-24Z M43 35l43 22 60-13M86 57v62" fill="none"/><g class="animated-fillers"><path d="m57 57 18-5 5 20-18 5Zm35 18 25-8 5 15-25 8Zm13-32 15 8-10 21-15-8Zm-37 41 23 9-6 15-23-9Z"/></g></g>';
 return '<g class="animated-extrusion"><path d="m24 40 52-10 86 26v37l-52 16-86-26Z M24 40l86 31 52-15M110 71v38"/><path class="animated-fluid" d="m37 58 31 10 62 15" fill="none"/></g>';
}
export function renderModelingPage(workflows,load){const {molecular,cross}=modelingRecords(workflows,load);
 return `<main class="modeling-page" data-ui><div class="modeling-columns">
 <section class="model-record-column" aria-label="微观分子建模记录"><header><div>${icon('molecule')}<h2>分子模型</h2><span>${molecular.length}</span></div><label class="model-record-search">${icon('search')}<input type="search" data-model-search="molecular" aria-label="搜索分子模型" placeholder="搜索分子模型"></label></header><div class="model-record-list">${molecular.map(r=>`<div class="model-record-wrap"><button class="model-record-card" data-model-molecule="${esc(r.id)}"><div class="model-thumbnail molecular-thumb">${moleculeThumbnail(r.molecule)}</div><div class="model-record-copy"><span class="model-record-kind">微观分子</span><h3>${esc(r.name)}</h3><p>${esc(r.molecule.name)} · ${esc(moleculeFormula(r.molecule))}</p><small>${esc(r.workflow?.name||'独立分子模型')}</small><time>${esc(r.time||'')}</time></div><span class="model-record-arrow">${icon('chevron')}</span></button><button class="model-record-delete" data-delete-molecule="${esc(r.id)}" aria-label="删除分子模型：${esc(r.name)}" title="删除分子模型">${icon('trash')}</button></div>`).join('')||'<div class="model-record-empty">还没有分子模型，创建第一个分子结构。</div>'}</div></section>
 <section class="model-record-column" aria-label="跨尺度建模记录"><header><div>${icon('flow')}<h2>跨尺度模型</h2><span>${cross.length}</span></div><label class="model-record-search">${icon('search')}<input type="search" data-model-search="cross" aria-label="搜索跨尺度模型" placeholder="搜索跨尺度模型"></label></header><div class="model-record-list">${cross.map(({workflow:w,macro})=>`<div class="model-record-wrap"><button class="model-record-card" data-action="edit" data-id="${esc(w.id)}"><div class="model-thumbnail macro-thumb">${macroThumbnail(macro)}</div><div class="model-record-copy"><span class="model-record-kind">${esc(algorithmName(macro?.params.case||w.type))}</span><h3>${esc(w.name)}</h3><p>${esc(w.description||'暂无备注')}</p><small>${w.nodeCount} 个节点 · ${esc(w.definitionStatus)}</small><time>${esc(w.updatedAt)}</time></div><span class="model-record-arrow">${icon('chevron')}</span></button><button class="model-record-delete" data-delete-cross-model="${esc(w.id)}" aria-label="删除跨尺度模型：${esc(w.name)}" title="删除跨尺度模型">${icon('trash')}</button></div>`).join('')}</div></section>
 <aside class="model-create-column model-create-types" aria-label="新建建模类型">${[
 ['molecule','微观分子建模','分子结构与三维预览','<g class="animated-molecule"><path d="m40 70 35-28 35 32 35-22"/><circle cx="40" cy="70" r="12"/><circle cx="75" cy="42" r="15"/><circle cx="110" cy="74" r="13"/><circle cx="145" cy="52" r="9"/></g>'],
 ['tim','TIM 材料建模','复合材料与导热模型','<g class="animated-tim"><path d="m43 35 60-13 43 22v60l-60 15-43-24Z M43 35l43 22 60-13M86 57v62"/><g class="animated-fillers"><circle cx="70" cy="66" r="7"/><circle cx="99" cy="59" r="8"/><circle cx="123" cy="78" r="7"/><circle cx="92" cy="92" r="8"/><circle cx="65" cy="87" r="6"/></g></g>'],
 ['extrusion','挤出流体模拟','管路结构与流动计算','<g class="animated-extrusion"><path d="m22 43 47-4 25 13 30-2 44 10v23l-44 8-30-1-25 13-47-4Z"/><path d="M69 39v64m25-51v38m30-40v41"/><path class="animated-fluid" d="M23 73h145"/></g>']
 ].map(([id,name,description,shape])=>`<button class="model-create-option create-${id}" data-model-new="${id}" aria-label="新建${name}"><span class="model-create-visuals"><svg class="model-create-art art-left" viewBox="0 0 190 140" aria-hidden="true">${shape}</svg><span class="model-create-option-plus">${icon('plus')}</span><svg class="model-create-art art-right" viewBox="0 0 190 140" aria-hidden="true">${alternateCreateArt(id)}</svg></span><span class="model-create-option-copy"><strong>${name}</strong><small>${description}</small></span><span class="model-create-option-arrow">${icon('chevron')}</span></button>`).join('')}</aside></div></main>`;
}
